benefits={
'849':'La copie conservée reste le double accessible selon LPF L106 ; aucune disparition de preuve ou d’accès pour les parties, héritiers, notaires ou recherches légalement autorisées. Les originaux, signatures et leur contrôle demeurent, et aucune certification nouvelle ni transmission numérique obligatoire ne remplace la signature retirée.',
'853':'Les actes restent enregistrables sans bordereau ni second exemplaire du bordereau. Les exonérations, paiements, dates et contrôles de fond ne changent pas ; les documents antérieurs réguliers demeurent valables et les sanctions non définitives bénéficient des règles ordinaires de loi plus douce.',
'855':'La quittance elle-même conserve sa valeur probante et ses règles ; ses références suffisent dans les documents dérivés. Ni attestation nouvelle, ni copie jointe, ni accès public aux données fiscales n’est ajouté ; les quittances antérieures restent valables et les droits ne sont pas payés deux fois.',
'856':'Le bail reste identifiable et l’enregistrement obligatoire reste vérifiable, sans reproduction littérale ni nouvelle pièce. Les exemptions de formalité et les actes déjà réguliers ne sont pas remis en cause ; le texte ne rétablit aucun droit fixe déjà supprimé ni frais de certification.',
'860':'Conserve le remplacement par reproduction partielle, les garanties cadastrales et foncières, l’authenticité et les droits des tiers. Préserve les gratuités et la suppression CSI déjà proposées et n’exige pas de projet de liquidation supprimé par255. Le coût des copies/transmissions supporté par les services reste inconnu, déjà rattaché à la mesure C et non nouvelle économie.',
'873':'Chaque objet, prix, signature, séance et mention d’inventaire subsiste intégralement ; la liberté d’écrire aussi en lettres reste ouverte. Les procès-verbaux anciens sont valables, aucun équipement ni certification supplémentaire n’est imposé et aucune exonération fiscale n’est retirée.',
'886':'Seul le relèvement au minimum0,08 euro disparaît ; les taux propres et toutes exemptions, remises et dispenses notamment890/891 subsistent. Pas de remboursement général du stock ancien, prélèvement de remplacement ni montant national économisé inventé. Le gain individuel peut être inférieur à0,08 euro et son application pratique reste à mesurer.',
'889':'Le détail de la dette, le total, la date et la signature restent exigibles, ainsi que l’option réglementaire de paiement comptant. Aucun raccourcissement du paiement en débet ni retrait d’une exonération ou d’une remise ; les visas anciens restent valables sans réédition.'}
benefits['862']='Tous les alinéas sources, exceptions de divorce, significations et publicité, anticipation notariale et champ limité des greffiers/INPI restent entiers hormis la coordination vers855. Les droits dus et les obligations de contrôle ne changent pas ; aucune nouvelle pièce, transcription ou sanction ne remplace la reproduction intégrale retirée. Les remises anciennes restent valables.'

for n in ['867','868']:
 benefits[n]='La fusion facultative préserve toutes catégories d’actes, champs de données, contrôles et accès légaux, y compris actes dispensés et bulletins3. Les exonérations et dispenses ne deviennent pas des obligations d’enregistrement. Anciens registres/numéros valables sans recopie, sans logiciel ou support imposé. Les actes et archives civiles/professionnelles restent conservés ; un seul paraphe selon les règles existantes suffit, sans redevance ou attestation de remplacement.'

a=[]
for x in s:
 n=x['number'];p=props.get(n);reason=meta[n][0]if p else retained[n]
 row={k:x[k]for k in ['code_id','source_id','source_sha256','number']};row.update(status='rewrite_draft'if p else'retained_unchanged',proposed_xml=p,reason=reason,review_notes='Source canonique et notes intégrales lues. '+(benefits[n]if p else retained[n]),benefit_review=benefits[n]if p else retained[n]+' Le corps source reste entier, sans nouvelle pièce, prélèvement ni restriction de bénéfice ; aucun gain de simplification n’est revendiqué.')
 effects=[]
 if p:
  r,mid,kind,sq,pq,bef,aft=meta[n];assert sq in x['source_xml'],(n,sq);assert pq in p,(n,pq)
  effects=[dict(kind=kind,measure_id=mid,description=r,before=bef,after=aft,unit='legal_duty'if n!='886'else'other',source_quote=sq,proposed_quote=pq,affected_population='Personnes et actes dans le seul champ complet de cet article, avec les exceptions, dispenses et avantages conservés.',conditions_and_transition='Entrée en vigueur de la loi proposée, sans date de promulgation inventée ; dossiers et droits anciens selon le texte entier. Aucun remboursement général ni réouverture de décisions définitives.',replacement_or_new_burdens='Les preuves utiles demeurent, sans nouvelle taxe, attestation ou équipement obligatoire. Le coût du traitement et les éventuels transferts vers les services ne sont pas chiffrés.')]
  row.update(change_type='full_repeal'if n in ['853','886']else'normative_reduction')
  if n in ['853','886']:row.update(repeal_policy_id='editorial_direction_2026_10_19',repeal_scope=reason+' Aucune suppression des droits fiscaux ou garanties autonomes non visés.')
  else:row.update(reform_policy_id='editorial_direction_2026_10_19',removed_provisions=[reason+' Le champ retiré est précisé dans le texte intégral et ne vaut pas abrogation des règles autonomes.'])
 row['substantive_impact']=dict(version=1,classification='coordination_only'if n in ['860','862']else'mixed'if n=='853'else'material_reduction'if p else'retained_necessary',assessment=reason+' '+(meta[n][5]+' → '+meta[n][6]if p else'Maintien intégral ; aucune simple synonymie présentée comme réécriture.'),scope_limitations='Lecture bornée de cet article et des cibles indiquées. Aucun solde national de complexité, coût ou recettes n’est établi. Les textes extérieurs non réécrits restent explicitement réservés.',new_burdens_review='Aucun prélèvement, équipement, déclaration de remplacement ou réduction d’exonération décidé. Les archives et données indispensables sont conservées. Les coûts publics et privés nets restent inconnus.',effects=effects)
 
 if n=='853':
  row['substantive_impact']['new_burdens_review']='Le relevé nécessaire au traitement est désormais établi par le service à partir des actes, et non fourni par le déposant. Cette charge de traitement peut transférer un coût vers l’administration ; effet net inconnu, aucune économie publique globale présumée.'
  row['substantive_impact']['effects'][0]['replacement_or_new_burdens']='Le déposant ne fournit plus de bordereau distinct. Le service établit les relevés nécessaires à partir des actes ; coût public de traitement et éventuelles reproductions à mesurer, aucun budget compensatoire inventé.'
 if n=='886':
  row['substantive_impact']['scope_limitations']+=' Le plancher légal est retiré, mais aucun tarif actuellement susceptible de produire moins de0,08 euro n’est identifié dans ce lot ; aucun gain effectif actuel, population ou recette nationale n’est démontré.'
 a.append(row)
